   279|  const newPassword = readTrimmed(input.newPassword) || readTrimmed(input.password);
   280|  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
   281|    throw new Error('A valid owner email is required for supabase_reset_owner_password.');
   282|  }
   283|  if (!newPassword || newPassword.length < 12) {
   284|    throw new Error('A new password of at least 12 characters is required for supabase_reset_owner_password (enterprise policy).');
   285|  }
   286|  const admin = resolveSupabaseAdminClient();
   287|  const { data: listData, error: listError } = await admin.auth.admin.listUsers({ page: 1, perPage: 1000 });
