   304|  try {
   305|    await admin.auth.admin.signOut(user.id, 'global');
   306|  } catch (signOutError) {
   307|    console.log('[SupabaseResetOwnerPassword] Session revocation note:', signOutError instanceof Error ? signOutError.message : 'unknown');
   308|  }
   309|  return {
   310|    provider: 'supabase',
   311|    action: 'supabase_reset_owner_password',
   312|    email,
