   314|    passwordReset: true,
   315|    sessionsRevoked: true,
   316|    emailConfirmed: Boolean(updateData.user.email_confirmed_at || updateData.user.confirmed_at) || true,
   317|    timestamp: nowIso(),
   318|    secretValuesReturned: false as const,
