import json, urllib.request, urllib.error, socket

DOMAIN = 'ivxholding.com'

def query_doh(name, type_):
    # Cloudflare DNS over HTTPS
    url = f'https://cloudflare-dns.com/dns-query?name={urllib.parse.quote(name)}&type={type_}'
    req = urllib.request.Request(url, headers={'Accept': 'application/dns-json'})
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        return {'error': e.code, 'body': e.read().decode()[:500]}

for type_ in ['A', 'MX', 'TXT', 'CNAME']:
    print(f'\n=== {type_} records for {DOMAIN} ===')
    data = query_doh(DOMAIN, type_)
    answers = data.get('Answer', [])
    if answers:
        for ans in answers:
            print(f"  {ans.get('type')}: {ans.get('data')}")
    else:
        print(f'  (none or error: {data})')

# Check common subdomains
for sub in ['_dmarc', 'default._domainkey', 'mail', 'noreply', 'www', 'api', 'chat']:
    name = f'{sub}.{DOMAIN}'
    print(f'\n=== TXT records for {name} ===')
    data = query_doh(name, 'TXT')
    answers = data.get('Answer', [])
    if answers:
        for ans in answers:
            print(f"  {ans.get('data')}")
    else:
        print(f'  (none)')

# SPF for root
print(f'\n=== SPF/DKIM/DMARC summary for {DOMAIN} ===')
root_txt = query_doh(DOMAIN, 'TXT')
for ans in root_txt.get('Answer', []):
    d = ans.get('data', '')
    if 'v=spf1' in d or 'DKIM' in d or 'DMARC' in d or 'amazonses' in d:
        print(f'  {d}')

dmarc = query_doh('_dmarc.ivxholding.com', 'TXT')
for ans in dmarc.get('Answer', []):
    print(f'  DMARC: {ans.get("data")}')
PYEOF

